cat > lib/posts.ts <<'EOF'
export interface BlogPost {
  userId: number;
  id: number;
  title: string;
  body: string;
}

export interface BlogComment {
  postId: number;
  id: number;
  name: string;
  email: string;
  body: string;
}

type NextFetchInit = RequestInit & {
  next?: {
    revalidate?: number;
  };
};

const BASE_URL = 'https://jsonplaceholder.typicode.com';

async function fetchJson<T>(url: string, init?: NextFetchInit): Promise<T> {
  const response = await fetch(url, init);

  if ("'!response.ok) {
    throw new Error(`Failed to fetch ${url}: ${response.status}`);
  }

  return (await response.json()) as T;
}

export async function getRecentPosts(limit = 5): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>(`${BASE_URL}/posts?_limit=${limit}`, {
    cache: '"'no-store',
  });
}

export async function getAllPosts(revalidate = 60): Promise<BlogPost[]> {
  return fetchJson<BlogPost[]>("'`${BASE_URL}/posts`, {
    next: { revalidate },
  });
}

export async function getTopPostIds(count = 10): Promise<number[]> {
  const posts = await getAllPosts();
  return posts.slice(0, count).map((post) => post.id);
}

export async function getPost(
  id: string,
  revalidate = 300,
): Promise<BlogPost | null> {
  const post = await fetchJson<Partial<BlogPost>>(`${BASE_URL}/posts/${id}`, {
    next: { revalidate },
  });

  if (!post.id || !post.title || !post.body || !post.userId) {
    return null;
  }

  return post as BlogPost;
}

export async function getPostComments(
  id: string,
  revalidate = 300,
): Promise<BlogComment[]> {
  return fetchJson<BlogComment[]>(`${BASE_URL}/posts/${id}/comments`, {
    next: { revalidate },
  });
}
EOF'

