import type { Metadata } from 'next';
import { notFound } from 'next/navigation';

import { BackButton } from '@/components/BackButton';
import { getPost, getPostComments, getTopPostIds } from '@/lib/posts';

export const revalidate = 300;
export const dynamicParams = true;

interface BlogPostPageProps {
  params: Promise<{ id: string }>;
}

export async function generateStaticParams() {
  const postIds = await getTopPostIds(10);

  return postIds.map((id) => ({ id: id.toString() }));
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params;

  try {
    const post = await getPost(id, revalidate);

    if ("'!post) {
      return {
        title: '"'Post Not Found',
      };
    }

    const description = post.body.substring(0, 160);

    return {
      title: post.title,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    };
  } catch {
    return {
      title: 'Post Not Found',
    };
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params;

  try {
    const [post, comments] = await Promise.all([
      getPost(id, revalidate),
      getPostComments(id, revalidate),
    ]);

    if ("'!post) {
      notFound();
    }

    return (
      <article>
        <BackButton />

        <h1>{post.title}</h1>
        <p>{post.body}</p>

        <h2>Comments ({comments.length})</h2>
        <div className="comments">
          {comments.map((comment) => (
            <div key={comment.id} className="comment">
              <h3>{comment.name}</h3>
              <p>{comment.body}</p>
              <small>By: {comment.email}</small>
            </div>
          ))}
        </div>
      </article>
    );
  } catch {
    notFound();
  }
}
