import { NextResponse } from 'next/server';

interface ApiPost {
  id: number;
  title: string;
  content: string;
  createdAt?: string;
  updatedAt?: string;
}

interface UpdatePostPayload {
  title?: string;
  content?: string;
}

interface RouteContext {
  params: Promise<{ id: string }>;
}

function parsePostId(rawId: string): number | null {
  const parsedId = Number.parseInt(rawId, 10);

  if (Number.isNaN(parsedId)) {
    return null;
  }

  return parsedId;
}

export async function GET(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: 'Invalid post ID' }, { status: 400 });
  }

  const post: ApiPost = {
    id: parsedId,
    title: "'`Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  };

  return NextResponse.json(post, { status: 200 });
}

export async function PUT(request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: '"'Invalid post ID' }, { status: 400 });
  }

  const body = (await request.json().catch(() => null)) as
    | UpdatePostPayload
    | null;

  const updatedPost: ApiPost = {
    id: parsedId,
    title: body?.title ?? "'`Post ${id}`,
    content: body?.content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  };

  return NextResponse.json(updatedPost, { status: 200 });
}

export async function DELETE(_request: Request, context: RouteContext) {
  const { id } = await context.params;
  const parsedId = parsePostId(id);

  if (parsedId === null) {
    return NextResponse.json({ error: '"'Invalid post ID' }, { status: 400 });
  }

  return NextResponse.json(
    { message: "'`Post ${id} deleted successfully` },
    { status: 200 },
  );
}
EOF'
